if(!EditorApplication.isPlaying)throw new System.Exception("Play only");var p=GameObject.Find("BB_Explorer_Locomotion03");var cc=p.GetComponent<CharacterController>();var motor=p.GetComponent<BlightBloom.Traversal.ThirdPersonMotor>();var orbit=Camera.main.GetComponent<BlightBloom.Traversal.ThirdPersonOrbitCamera>();var position=p.transform.position;var rotation=p.transform.rotation;bool me=motor.enabled,oe=orbit.enabled;var terrain=Terrain.activeTerrain;var results=new System.Collections.Generic.List<object>();var cameras=new System.Collections.Generic.List<object>();Vector3 Ground(float x,float z){return new Vector3(x,terrain.SampleHeight(new Vector3(x,0,z))+terrain.transform.position.y+.03f,z);}
