finally{cc.enabled=false;p.transform.SetPositionAndRotation(position,rotation);cc.enabled=true;motor.enabled=me;orbit.enabled=oe;Physics.SyncTransforms();}var result=new{method="Automated existing CharacterController.Move trunk blocking and camera-equivalent sphere casts, not manual camera comfort",trunks=results,allTrunksBlock=results.All(r=>(bool)r.GetType().GetProperty("blocked").GetValue(r)),cameraSamples=cameras,minimumCameraDistance=cameras.Min(r=>(float)r.GetType().GetProperty("safeDistance").GetValue(r)),normalStateRestored=motor.enabled==me&&orbit.enabled==oe};System.IO.File.WriteAllText("ArtSource/Pipeline/Review/BriarwickEnvironment06_Revision01/TrunkCameraValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return new{trunkTests=results.Count,result.allTrunksBlock,cameraTests=cameras.Count,result.minimumCameraDistance,result.normalStateRestored};
